// InternalKey ordering: userKey ASC, seqNum DESC (newest version first)
record InternalKey(byte[] userKey, long seqNum, byte opType) implements Comparable<InternalKey> {
    @Override
    public int compareTo(InternalKey other) {
        int cmp = Arrays.compareUnsigned(this.userKey, other.userKey);
        if (cmp != 0) return cmp;
        return Long.compare(other.seqNum, this.seqNum);
    }
}

public byte[] get(byte[] userKey) {
    // 1. Check active & immutable MemTables
    byte[] val = findInMemTable(activeMemTable, userKey);
    if (val != null) return val == TOMBSTONE ? null : val;
    for (MemTable imm : immutableMemTables) {
        val = findInMemTable(imm, userKey);
        if (val != null) return val == TOMBSTONE ? null : val;
    }
    // 2. Check all overlapping L0 SSTables newest-first
    Version v = currentVersion.acquire();
    try {
        for (SSTableMeta sst : v.level0FilesNewestFirst()) {
            if (!sst.bloomFilter.mightContain(userKey)) continue;
            byte[] res = sst.searchDataBlock(userKey, blockCache);
            if (res != null) return res == TOMBSTONE ? null : res;
        }
        // 3. Check L1..Ln (at most 1 SSTable per level)
        for (int lvl = 1; lvl < v.numLevels(); lvl++) {
            SSTableMeta sst = v.binarySearchLevel(lvl, userKey);
            if (sst == null || !sst.bloomFilter.mightContain(userKey)) continue;
            byte[] res = sst.searchDataBlock(userKey, blockCache);
            if (res != null) return res == TOMBSTONE ? null : res;
        }
        return null;
    } finally {
        v.release();
    }
}

// Leveled compaction trigger: pick level with highest score (size / maxBytesForLevel)
double maxScore = 0.0;
int targetLevel = -1;
for (int lvl = 0; lvl < numLevels - 1; lvl++) {
    double score = (lvl == 0)
        ? (double) l0Files.size() / 4.0
        : (double) levelBytes[lvl] / (256L * 1024 * 1024 * Math.pow(10, lvl - 1));
    if (score > maxScore) { maxScore = score; targetLevel = lvl; }
}

// Proactive write backpressure before hitting hard L0 limit (24)
int l0Count = currentVersion.l0FileCount();
if (l0Count >= 24) {
    waitForCompactionSignal();
} else if (l0Count >= 12) {
    long delayMicros = (l0Count - 11) * 20L;
    LockSupport.parkNanos(delayMicros * 1_000L);
}

// WiscKey-style value pointer stored inline in SSTable instead of 10 KB blob
record ValuePointer(long vLogFileId, long offset, int length) {
    byte[] encode() {
        return ByteBuffer.allocate(20).putLong(vLogFileId).putLong(offset).putInt(length).array();
    }
}
